# Disable Windows Lock Screen Write-Host "Disabling Windows lock screen..." -ForegroundColor Cyan # Disable lock screen via group policy Set-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\Personalization" -Name "NoLockScreen" -Value 1 -Type DWord -Force -ErrorAction Stop Write-Host "Lock screen has been disabled. You will go directly to the login screen." -ForegroundColor Green